fn floor_plan(a:&State)->String{let m=&a.m;let(w,d)=(n(m,"w"),n(m,"d"));let mut o=format!("<svg class=floorplan viewBox=\"-3 -3 {} {}\" role=img aria-label=\"Clickable wall and room plan\"><text x={} y=-1 text-anchor=middle class=plan-dimension font-size={:.2}>{} ft</text>",if a.c.active_floor==0&&m["siteBounds"].is_object(){n(&m["siteBounds"],"maxX")-n(&m["siteBounds"],"minX")+6.}else{w+6.},if a.c.active_floor==0&&m["siteBounds"].is_object(){n(&m["siteBounds"],"maxZ")-n(&m["siteBounds"],"minZ")+6.}else{d+6.},w/2.,(w.max(d)/30.).clamp(0.9,2.4),w);if a.c.active_floor==0&&m["siteBounds"].is_object(){o=o.replace("viewBox=\"-3 -3",&format!("viewBox=\"{} {}",n(&m["siteBounds"],"minX")-3.,n(&m["siteBounds"],"minZ")-3.));}for r in m["rooms"].as_array().unwrap(){let(x,z,rw,rd)=(n(r,"x"),n(r,"z"),n(r,"w"),n(r,"d"));o.push_str(&format!("<g data-room=\"{}\" tabindex=0 role=button aria-label=\"Enter {}\"><rect x={} y={} width={} height={} class=\"room {}\"/><text x={} y={} font-size={} text-anchor=middle>{}</text></g>",s(r,"id"),esc(s(r,"name")),x,z,rw,rd,s(r,"type"),x+rw/2.,z+rd/2.,(rw/(s(r,"name").len()as f64*0.6)).min(rd/3.).min((w.max(d)/55.).max(0.65)),esc(s(r,"name"))));}for wall in m["walls"].as_array().unwrap(){let(x,z,len)=(n(wall,"x"),n(wall,"z"),n(wall,"length"));let along=s(wall,"axis")=="x";let point=|at:f64|(x+if along{at}else{0.},z+if along{0.}else{at});let(x2,z2)=point(len);o.push_str(&format!("<g data-reference-wall=\"{}\" aria-label=\"{}\"><line x1={} y1={} x2={} y2={} stroke=transparent stroke-width=1.4/><line x1={} y1={} x2={} y2={} stroke=\"{}\" stroke-width=.28/>",s(wall,"id"),esc(s(wall,"name")),x,z,x2,z2,x,z,x2,z2,if s(wall,"id")==a.wall{"#f3cd43"}else{"#c7cbbc"}));for op in wall["openings"].as_array().unwrap(){let(x1,z1)=point(n(op,"at"));let(x2,z2)=point(n(op,"at")+n(op,"width"));o.push_str(&format!("<line x1={} y1={} x2={} y2={} stroke=\"{}\" stroke-width=.4><title>{}: {} × {} ft</title></line>",x1,z1,x2,z2,if s(op,"kind")=="window"{"#83c7e9"}else{"#de9865"},s(op,"id"),n(op,"width"),n(op,"height")));}o.push_str("</g>");}if a.c.active_floor==0{o.push_str(&garage_plan(m));if let Some(rects)=m["porch"]["rectangles"].as_array(){for r in rects{o.push_str(&format!("<rect class=porch-plan x={} y={} width={} height={} fill=\"#b8a881\" fill-opacity=.45 stroke=\"#796c4c\" stroke-width=.1><title>Covered porch · {} × {} ft</title></rect>",n(r,"x"),n(r,"z"),n(r,"w"),n(r,"d"),n(r,"w"),n(r,"d")));}}}o.push_str("</svg>");o}
