fn structural_html(a:&State)->String{let check=&a.m["structural"];let mut out=String::from("<section class=structural-status role=status aria-label=\"Structural review status\"><strong>Structural review required</strong>");let f=&check["floor"];if f.is_object(){out.push_str(&format!("<p>Longest floor clear span {:.2} ft · {} in O.C. · {:.0} psf live / {:.0} psf dead.</p>",n(f,"maxClearSpan"),n(f,"spacingInches"),n(f,"liveLoadPsf"),n(f,"deadLoadPsf")));if f["candidate"].is_object(){out.push_str(&format!("<p>Preliminary candidate: {} · {:.3} in deep. Uniform-load table screening only.</p>",esc(s(&f["candidate"],"series")),n(&f["candidate"],"depthInches")));}else{out.push_str("<p>No joist candidate meets the implemented span-table conditions.</p>");}
  if let Some(lines)=f["girderLines"].as_array().filter(|v|!v.is_empty()){out.push_str(&format!("<p>Upper-floor girder lines at {} ft, over the foundation girders, on posts down to the {}.</p>",lines.iter().map(|v|format!("{}",v.as_f64().unwrap_or(0.))).collect::<Vec<_>>().join(", "),if a.c.foundation==piers::HELICAL{"piers"}else{"crawlspace piers"}));}}
  let g=&check["mainFloor"];if g.is_object(){out.push_str(&format!("<p>Main floor: {} foundation girder lines · longest clear span {:.2} ft{}.</p>",n(g,"girderLines"),n(g,"maxClearSpan"),g["candidate"].as_str().map_or(" · no table candidate".to_string(),|p|format!(" · {} candidate",esc(p)))));}out.push_str("<details><summary>View structural warnings</summary><ul>");for issue in check["issues"].as_array().unwrap(){out.push_str(&format!("<li>{}</li>",esc(issue.as_str().unwrap_or(""))));}out.push_str("</ul></details><p>ForteWEB: not connected · analysis has not run. Design changes remain available.</p></section>");out}
