fn modal(a:&State)->String{if a.modal.is_empty(){return String::new()}if a.modal=="legal"{return legal::html()}let mut o=format!("<div class=modal-shade><section class=report-modal role=dialog aria-modal=true aria-labelledby=report-title><button class=close-modal data-action=close aria-label=\"Close report\">×</button><p class=kicker>UF–{} / ENGINEER HANDOFF</p><h2 id=report-title>{}</h2>",a.c.seed,if a.modal=="forte"{"Continue with ForteWEB"}else{"Your design report"});if a.modal=="forte"{o.push_str("<p>ForteWEB is free with an account. Download the job file below and import it by hand; automatic exchange (send the file, get design results and PDF reports back) uses Weyerhaeuser’s ForteWEB API, which Weyerhaeuser sets up once a .4te file has been created.</p><div class=notice><strong>ForteWEB job file</strong><p>Download this design as a ForteWEB file (.4te): floor joists for each floor, upper-floor girders, a header for every door and window size, and the roof rafters, with the loads each one carries. In ForteWEB, open the File Manager, choose Import and pick the file; ForteWEB then sizes each member and prints a report. Loads are preliminary (40/20 psf floors, 20 psf roof live, 30 psf snow, 15 psf roof dead); confirm site loads, bearings and connections there.</p></div><div class=report-downloads>");o.push_str(&btn("forte4te","Download ForteWEB file (.4te)","primary"));o.push_str("<a class=\"button secondary\" href=https://www.forteweb.com/ target=_blank rel=noopener>Open ForteWEB</a><a class=\"button secondary\" href=https://www.weyerhaeuser.com/woodproducts/software-learning/forte-software/weyerhaeuser-interoperability-license/ target=_blank rel=noopener>Request official SDK</a>");o.push_str(&btn("framing","Download framing CSV","secondary"));o.push_str(&btn("json","Download design JSON","secondary"));}else{o.push_str(&format!("<p>Floor plan, opening dimensions, every framing piece, insulation profile, electrical allowances and itemized costs.</p><label class=field>Project name / site address<input data-field=project value=\"{}\" maxlength=160 placeholder=\"Project or site name\"></label><div class=notice><strong>Engineering analysis pending</strong><p>ZIP-based climate data is included. Site loads, local code adoption, structural capacity and construction compliance are not certified. No separate vapor membrane has been priced.</p></div><div class=report-downloads>",esc(&a.project)));o.push_str("</div>");o.push_str(&structural_html(a));o.push_str("<div class=report-downloads>");for(action,label)in[("pdf","Download report PDF"),("csv","Material & cost CSV"),("framing","Every framing piece CSV"),("json","Design JSON"),("forte","ForteWEB connection")]{o.push_str(&btn(action,label,if action=="pdf"{"primary"}else{"secondary"}));}}o.push_str("</div><p class=muted>Ready to share for professional review. This is a design and estimating package, not an approved construction set.</p></section></div>");o}
/// The 3D view's payload is serialized straight from the live state, without copying the model first,
/// and without the report-only schedules (reports build their own full payload).
struct Slim<'a>(&'a Value,bool);
const REPORT_ONLY:[&str;16]=["allFrameMembers","allTrimPieces","allRooms","allOpenings","allFurniture","allSpans","allTrimOrnaments","studs","mainRafterStock","dormerFrameMembers","dormerRafters","spans","piecesByRole","electrical","openingChecks","finishRooms"];
const LEVEL_ONLY:[&str;7]=["items","categoryTotals","panelAssemblies","subtotal","tax","total","ventilation"];
impl Serialize for Slim<'_>{fn serialize<S:serde::Serializer>(&self,ser:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeMap;let Some(obj)=self.0.as_object()else{return self.0.serialize(ser)};let mut map=ser.serialize_map(None)?;
 for(k,v)in obj{if REPORT_ONLY.contains(&k.as_str())||(!self.1&&LEVEL_ONLY.contains(&k.as_str())){continue}if self.1&&k=="levels"{if let Some(levels)=v.as_array(){map.serialize_entry(k,&levels.iter().map(|l|Slim(l,false)).collect::<Vec<_>>())?;continue}}map.serialize_entry(k,v)?;}map.end()}}
#[derive(Serialize)]#[serde(rename_all="camelCase")]struct ScenePayload<'a>{config:&'a Config,model:Slim<'a>,view:&'a str,jump:&'a str,frame_roof:bool,frame_opening:&'a str,selection:&'a Value,camera_revision:u32}
fn render(redraw:bool){if PENDING.with(|p|p.get())!=0{return}let next_scene=STATE.with(|cell|{let a=cell.borrow();html("generator",&generation_controls(&a));html("header-modes",&mode_buttons(&a));html("controls",&controls(&a));html("viewbar",&viewbar(&a));html("scene-ui",&scene_ui(&a));html("context",&editor::menu(&a));html("stats",&stats(&a));html("estimate",&estimate(&a));html("modal",&modal(&a));notice(&a.message);el("visual").set_class_name(if a.full{"visual-panel expanded"}else{"visual-panel"});el("scene").set_attribute("style",if a.view=="plan"{"visibility:hidden"}else{"visibility:visible"}).ok();el("keep-size").dyn_ref::<HtmlInputElement>().unwrap().set_checked(a.keep_size);if redraw{Some(serde_json::to_string(&ScenePayload{config:&a.c,model:Slim(&a.m,true),view:&a.view,jump:&a.room,frame_roof:a.roof,frame_opening:&a.frame_opening,selection:&a.selection,camera_revision:a.camera_revision}).unwrap_or_default())}else{None}});if let Some(payload)=next_scene{scene(&payload)}editor::sync();}
fn val(id:&str)->String{let e=el(id);if let Some(i)=e.dyn_ref::<HtmlInputElement>(){engine_value(&e,i.value())}else if let Some(s)=e.dyn_ref::<HtmlSelectElement>(){s.value()}else{String::new()}}
fn command_direction(target:&Element)->&'static str{match target.get_attribute("data-action").unwrap_or_default().as_str(){"camera-left"=>"left","camera-right"=>"right","camera-front"=>"front","camera-rear"=>"rear","camera-in"=>"in","camera-rotate-left"=>"rotate-left","camera-rotate-right"=>"rotate-right","camera-tilt-up"=>"tilt-up","camera-tilt-down"=>"tilt-down",_=>"out"}}
fn rand(n:usize)->usize{(js_sys::Math::random()*n as f64).floor()as usize}
fn apply_home(c:&mut Config){let h=lookup("homeStyles",&c.home_style);c.siding=s(&h,"cladding").into();c.pitch=n(&h,"pitch");c.trim_package=s(&h,"trim").into();for(key,src)in[("siding","siding"),("roof","roof"),("trim","exteriorTrim")]{c.colors.insert(key.into(),s(&h,src).into());}}
fn apply_interior(c:&mut Config){c.room_wallpapers.clear();c.wallpaper="None".into();c.bedroom_wallpaper="None".into();let i=lookup("interiorSchemes",&c.interior_style);c.floor=s(&i,"floor").into();c.drywall=s(&i,"drywall").into();for(k,v)in i["colors"].as_object().unwrap(){c.colors.insert(k.clone(),v.as_str().unwrap().into());}}
