const SESSION_KEY:&str="uf-session-design";
fn session()->Option<web_sys::Storage>{web_sys::window()?.session_storage().ok().flatten()}
fn remember_session(c:&Config){if let Some(s)=session(){let _=s.set_item(SESSION_KEY,&serde_json::to_string(c).unwrap_or_default());}}
/// Post-model bookkeeping: keep the selected room, wall, opening and category valid.
fn settle(a:&mut State){if !a.m["rooms"].as_array().unwrap().iter().any(|r|s(r,"id")==a.room){a.room="living".into();}if !a.m["openings"].as_array().unwrap().iter().any(|o|s(o,"id")==a.frame_opening){a.frame_opening.clear();}if a.category!="All materials"&&a.m["categoryTotals"].get(&a.category).is_none(){a.category="All materials".into();}if !a.m["walls"].as_array().unwrap().iter().any(|w|s(w,"id")==a.wall){a.wall="E1".into();}a.message.clear();if a.m["structural"]["floor"].is_object()&&a.m["structural"]["floor"]["candidate"].is_null(){a.message="Joist span/loading needs an engineered solution. See Structural review below the price.".into();}}
/// Builds the model here and now; a worker reply still on its way is for an older design, so it is dropped.
fn fresh(c:&Config)->Value{PENDING.with(|p|p.set(0));REDRAW.with(|r|r.set(false));model::build(c)}
fn changed(a:&mut State){PENDING.with(|p|p.set(0));if !commit(a){return}a.m=fresh(&a.c);settle(a);}
/// Form changes are calculated by the engine worker off the main thread; the studio redraws when the
/// model arrives. Without a worker (or if it fails) the model is built here, as before.
/// Every request gets a new sequence number, so a late reply can never be mistaken for the current one.
fn changed_async(a:&mut State)->bool{if !commit(a){return false}let seq=NEXT_SEQ.with(|n|{let v=n.get().wrapping_add(1).max(1);n.set(v);v});let config=serde_json::to_string(&a.c).unwrap_or_default();PENDING.with(|p|p.set(seq));if request_model(&config,seq).unwrap_or(false){SENT.with(|s|*s.borrow_mut()=config);return true}a.m=fresh(&a.c);settle(a);false}
pub fn apply_model(seq:u32,json:&str){if seq==0||PENDING.with(|p|p.get())!=seq{return}PENDING.with(|p|p.set(0));let redraw=REDRAW.with(|r|r.replace(false));STATE.with(|cell|{let mut a=cell.borrow_mut();let current=serde_json::to_string(&a.c).unwrap_or_default()==SENT.with(|s|s.borrow().clone());match serde_json::from_str::<Value>(json){Ok(m) if m.is_object()&&current=>a.m=m,_=>a.m=fresh(&a.c)}settle(&mut a);});render(redraw);}
