fn notice(text:&str){
 let converted;let text=if units::metric(){converted=units::metricize(text);converted.as_str()}else{text};
 let message=el("message");if message.text_content().as_deref()==Some(text){return}
 let window=web_sys::window().unwrap();NOTICE.with(|saved|{if let Some((id,_))=saved.borrow_mut().take(){window.clear_timeout_with_handle(id)}});
 message.set_text_content(Some(text));message.set_class_name(if text.is_empty(){"toast hidden"}else{"toast"});if text.is_empty(){return}
 let callback=Closure::<dyn FnMut()>::new(||{STATE.with(|a|a.borrow_mut().message.clear());let message=el("message");message.set_text_content(Some(""));message.set_class_name("toast hidden");});
 let id=window.set_timeout_with_callback_and_timeout_and_arguments_0(callback.as_ref().unchecked_ref(),6000).unwrap();NOTICE.with(|saved|*saved.borrow_mut()=Some((id,callback)));
}
