fn storage()->Option<web_sys::Storage>{web_sys::window()?.local_storage().ok().flatten()}
/// Hand the current design to the process simulator, keep a copy to restore on the way back, then go.
/// The studio's exterior 3D house is exported alongside, so the simulator builds this exact house.
/// `live`: the 3D view on screen shows this exact model, so the simulator can be handed that scene.
fn open_process(a:&State,live:bool){let design=process::handoff(&a.c,&a.m).to_string();if let Some(s)=storage(){let _=s.set_item(process::HANDOFF_KEY,&design);let _=s.set_item(process::RETURN_KEY,&serde_json::to_string(&a.c).unwrap_or_default());}let scene=serde_json::to_string(&ScenePayload{config:&a.c,model:Slim(&a.m,true),view:"exterior",jump:&a.room,frame_roof:false,frame_opening:"",selection:&Value::Null,camera_revision:a.camera_revision}).unwrap_or_default();open_process_js(&scene,&design,live);}
/// Coming back from the process page restores the design the visitor left with.
fn restore_design(){let handed=storage().and_then(|s|{let t=s.get_item(process::RETURN_KEY).ok().flatten();let _=s.remove_item(process::RETURN_KEY);t});let Some(text)=handed.or_else(||session().and_then(|s|s.get_item(SESSION_KEY).ok().flatten()))else{return};if let Ok(c)=security::parse(&text){if validate(&c).is_ok(){STATE.with(|cell|{let mut a=cell.borrow_mut();a.m=model::build(&c);a.previous=c.clone();a.c=c;});}}}
