 let mut out=format!("<div class=profile><span class=kicker>OPENING HEIGHT GUARDRAILS · {}</span><p>Door rough opening: at least 82.5 in, zero sill. Selected door must provide 78 in finished clear height.</p><p>Bedroom window rough sill: 24–42 in. Selected escape window clear sill: at most 44 in.</p><p class=muted>Heights are measured above finished floor. Window net clear area and product frame dimensions require confirmation.</p><details class=code-details><summary>{} modeled openings · height schedule</summary>",esc(&a.c.building_code),checks["schedule"].as_array().unwrap().len());
 for o in checks["schedule"].as_array().unwrap(){out.push_str(&format!("<p>{} · {} · {:.2} in rough height · {:.2} in rough sill · {}</p>",esc(s(o,"id")),esc(s(o,"kind")),n(o,"roughHeightInches"),n(o,"roughSillInches"),if o["heightGuardrailPass"]==true{"Height guardrail passed"}else{"Height review required"}));}
 for issue in checks["issues"].as_array().unwrap(){out.push_str(&format!("<p>{}</p>",esc(issue.as_str().unwrap_or(""))));}
 out.push_str("<a target=_blank rel=noopener href=\"https://codes.iccsafe.org/content/IRC2021P1/chapter-3-building-planning\">IRC residential opening rules</a></details></div><details class=code-details><summary>Roof ventilation · product ratings</summary><p>Vented attic uses the conservative 1:150 area basis. Enter each selected product’s net free area (NFA), after screens and louvers.</p>");
 for(key,label,value)in[("ridgeVentNfa","Ridge vent · in² NFA per ft",a.c.ridge_vent_nfa),("soffitVentNfa","Soffit insert · in² NFA each",a.c.soffit_vent_nfa),("roofVentNfa","Box vent · in² NFA each",a.c.roof_vent_nfa)]{out.push_str(&field_num(key,label,value,0.1,1000.));}
 out.push_str(&format!("<p>Required: {:.2} in² NFA. Modeled exhaust: {:.2} in²; intake: {:.2} in². {:.0} supplemental roof vents, {:.0} soffit inserts.</p><p class=muted>Confirm product ratings, vent spacing and the complete roof assembly before approval.</p>{}</details>",n(v,"requiredNfaSquareInches"),n(v,"exhaustNfa"),n(v,"intakeNfa"),n(v,"boxVentCount"),n(v,"intakeVentCount"),if v["cathedral"]==true{format!("<p class=feature-note>{}{}</p>",esc(s(v,"basis")),if v["passesArea"]==true{""}else{" This roof does not reach the 1:150 area with its ridge vent alone."})}else{String::new()}));
