fn panel_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=panels><summary>Universal Frame panel assemblies</summary><p class=muted>Factory panel defaults. The standard precut plus three plates is 97-1/8 in; 8, 9 and 10 ft custom walls use cut stock.</p>");
 for panel in a.m["panelAssemblies"].as_array().into_iter().flatten(){out.push_str(&format!("<details class=assembly-card><summary>{}</summary><p>{}</p><ol>",esc(s(panel,"name")),esc(s(panel,"module"))));for layer in panel["layers"].as_array().into_iter().flatten(){out.push_str(&format!("<li>{}</li>",esc(layer.as_str().unwrap_or(""))));}out.push_str("</ol></details>");}
 out.push_str(&select("roofInsulation","Roof batt package",&strings(&["R-49","R-38 HD + R-11"]),&a.c.roof_insulation));
 for (field,label,value) in [("interiorSound","Bedroom / bath R-13 sound batts",a.c.interior_sound),("upperSound","Upper-floor R-19 sound batts",a.c.upper_sound)]{out.push_str(&format!("<label class=check><input type=checkbox data-field={} {}>{}</label>",field,checked(value),label));}
 out.push_str("<p class=muted>Required R-value and installed product performance are separate. Header selections and I-joist series remain subject to load and manufacturer review.</p></details>");out
}
fn surface_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=surfaces><summary>Tile walls &amp; upload a pattern</summary><p class=muted>Tiles cover the chosen room group. Uploaded patterns repeat at a real-world size and travel with downloaded design JSON.</p>");
 let mut names=vec!["None".to_string()];names.extend(surfaces::tiles().as_array().unwrap().iter().map(|t|s(t,"name").to_string()));
 for (key,label) in [("bedroom","Bedroom walls"),("general","Rest of house walls")]{let value=a.c.wall_tiles.get(key).map(String::as_str).unwrap_or("None");out.push_str(&select(key,&format!("{} · tile",label),&names,value).replace(&format!("data-field=\"{}\"",key),&format!("data-wall-tile=\"{}\"",key)));}
 for (key,label) in [("bedroom","Bedroom walls"),("general","Rest of house walls"),("floor","All house floors")]{let pattern=a.c.custom_textures.get(key);out.push_str(&format!("<div class=texture-control><strong>{}</strong><label class=field>Pattern repeat · ft<input type=number min=.25 max=16 step=.25 data-texture-repeat=\"{}\" data-pattern-repeat=\"{}\" value=\"{}\"></label><label class=texture-upload>Upload JPEG / PNG / WebP<input type=file accept=\"image/jpeg,image/png,image/webp\" data-texture-upload=\"{}\"></label>",label,key,key,pattern.map_or(2.,|p|p.repeat_feet),key));if let Some(p)=pattern{out.push_str(&format!("<div class=texture-current><img src=\"{}\" alt=\"Uploaded repeating pattern\"><span>{}</span><button class=text data-action=texture-remove data-value={}>Remove</button></div>",esc(&p.data_url),esc(&p.name),key));}out.push_str("</div>");}
 out.push_str("<p class=muted>Up to 12 MB input; resized and stored as bounded JPEG. A tile selection replaces the custom wall pattern in that group.</p></details>");out
}
pub fn texture(input:&str){
 let Ok(v)=serde_json::from_str::<Value>(input)else{return};let key=s(&v,"target");if !["bedroom","general","floor"].contains(&key){return}
 let Ok(pattern)=serde_json::from_value::<surfaces::TexturePattern>(v["pattern"].clone())else{return};
 STATE.with(|cell|{let mut a=cell.borrow_mut();a.c.custom_textures.insert(key.into(),pattern);if key!="floor"{a.c.wall_tiles.remove(key);if key=="bedroom"{a.c.bedroom_wallpaper="None".into();}else{a.c.wallpaper="None".into();}}changed(&mut a);});render(true);
}

/// Floors by area: the kitchen shares the bathrooms' floor; living areas and bedrooms each get their own, or the house floor.
fn zone_floor_controls(c:&Config)->String{
 let mut out=String::from("<details class=zone-floors open><summary>Floors by area</summary><p class=muted>Split the flooring: kitchen and bathrooms share one floor, living areas and bedrooms can each have another.</p>");
 for(key,label)in finishes::ZONES{let value=c.zone_floors.get(key).map(String::as_str).unwrap_or("House floor");let mut list=vec!["House floor".to_string()];list.extend(choices("floor"));
  out.push_str(&format!("<label class=field>{label}<select data-zone-floor=\"{key}\">{}</select></label>",opts(&list,value)));}
 out.push_str("</details>");out
}
fn room_finish_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=room-finishes><summary>Wallpaper each room individually</summary><p class=muted>Use a house default or choose a different pattern for each room. Individual choices replace that room's group tile or uploaded wall pattern. Choose None for painted drywall.</p>");
 let levels=a.m["levels"].as_array().map(|ls|ls.iter().collect::<Vec<_>>()).unwrap_or_else(||vec![&a.m]);let mut names=vec!["House default".to_string()];names.extend(choices("wallpaper"));
 for level in levels{let floor=n(level,"floorIndex")as usize;out.push_str(&format!("<h4>{}</h4>",if floor==0{"Main floor"}else{"Upper floor"}));for room in level["finishRooms"].as_array().into_iter().flatten(){if s(room,"type")=="stairs"{continue}let id=s(room,"id");let value=a.c.room_wallpapers.get(id).map(String::as_str).unwrap_or("House default");let label=format!("{} · wallpaper",s(room,"name"));out.push_str(&select(id,&label,&names,value).replace(&format!("data-field=\"{}\"",id),&format!("data-room-wallpaper=\"{}\"",id)));}}
 out.push_str("<p class=muted>In blank slate, full separating walls define individual rooms; partial walls remain part of the same space.</p></details>");out
}
fn garage_entry_controls(a:&State)->String{
 if a.c.garage!="Attached"{return String::new()}let ground=if a.c.stories>=2{&a.m["levels"][0]}else{&a.m};
 let garage_z=n(&a.m["garage"],"z");let mut out=String::new();
 // Slide the whole garage along the side of the house (its front edge, in feet from the house front).
 out.push_str(&format!("<label class=field>Garage position · {} ft from house front<input type=range data-field=garageOffset aria-label=\"Garage position along the house\" min=-16 max={} step=2 value=\"{}\"></label><p class=muted>Slide the garage along the side of the house; negative values set it forward of the front wall. {}</p>",garage_z,(a.c.depth-8.).max(0.),garage_z,if a.c.garage_offset.is_some(){"<button class=\"button secondary\" data-action=garage-auto>Place automatically</button>"}else{"Placed automatically."}));
 let rs:Vec<Room>=serde_json::from_value(ground["rooms"].clone()).unwrap_or_default();let ws:Vec<Wall>=serde_json::from_value(ground["walls"].clone()).unwrap_or_default();
 for w in ground["walls"].as_array().into_iter().flatten(){if let Some(o)=w["openings"].as_array().unwrap().iter().find(|o|s(o,"id")=="G-HOUSE-DOOR"){let center=n(w,"z")+n(o,"at")+n(o,"width")/2.;
  let spans=garage::connection_spans(&a.c,&rs,&ws);let (lo,hi)=(spans.first().map_or(center,|s|s.0),spans.last().map_or(center,|s|s.1));
  let allowed=spans.iter().map(|(x,y)|if (y-x).abs()<0.01{format!("{:.1} ft",x)}else{format!("{:.1}–{:.1} ft",x,y)}).collect::<Vec<_>>().join(", ");
  out.push_str(&format!("<label class=field>House–garage door · {:.1} ft from house front<input type=range data-garage-entry aria-label=\"House–garage door center\" min={:.2} max={:.2} step=0.25 value=\"{:.2}\"></label><p class=muted>Allowed along the shared wall: {}. A garage door can't open into a bedroom (IRC R302.5.1) or onto a stair run; a blocked spot snaps to the nearest allowed one. You can also click the door in 3D and edit its Start.</p>",center,lo,hi,center,allowed));return out}}
 out.push_str("<p class=muted>No shared doorway fits where the garage sits. Slide the garage, choose the other side, or revise the adjoining room.</p>");out
}
